" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"830\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\">A legal brief, not a manifesto</text></svg>",
