            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">PRACTICE: BE PUBLIUS</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Defend the Constitution in 200 words</text><rect x=\"80\" y=\"200\" width=\"940\" height=\"180\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/><text x=\"550\" y=\"255\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"22\">ANTI-FEDERALIST CHARGE</text><text x=\"550\" y=\"305\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Article I, Section 8 + N&P Clause =</text><text x=\"550\" y=\"345\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">unlimited Congressional power</text><rect x=\"80\" y=\"410\" width=\"440\" height=\"200\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"300\" y=\"470\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"22\">ANSWER 1</text><text x=\"300\" y=\"520\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">Enumerated powers</text><text x=\"300\" y=\"555\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">are a CLOSED list</text><text x=\"300\" y=\"590\" text-anchor=\"middle\" fill=\"#888\" font-size=\"17\">10th Amendment locks it</text><rect x=\"580\" y=\"410\" width=\"440\" height=\"200\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"800\" y=\"470\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"22\">ANSWER 2</text><text x=\"800\" y=\"520\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">Federalist No. 51:</text><text x=\"800\" y=\"555\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">4 other branches push</text><text x=\"800\" y=\"590\" text-anchor=\"middle\" fill=\"#888\" font-size=\"17\">veto, court, senate, house</text><rect x=\"100\" y=\"650\" width=\"900\" height=\"220\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"710\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"22\">KEY MOVE</text><text x=\"550\" y=\"760\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">The Constitution does not TRUST Congress.</text><text x=\"550\" y=\"800\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">It SURROUNDS Congress.</text><text x=\"550\" y=\"845\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Inhabit the argument to understand it.</text></svg>",
