            "type": "diagram",
            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">PRACTICE: BOTH SIDES</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Argue a constitutional conflict</text><rect x=\"80\" y=\"190\" width=\"940\" height=\"120\" rx=\"18\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"2\"/><text x=\"550\" y=\"240\" text-anchor=\"middle\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"24\">THE CONFLICT</text><text x=\"550\" y=\"285\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Executive order on school curriculum</text><rect x=\"60\" y=\"350\" width=\"490\" height=\"320\" rx=\"20\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"305\" y=\"410\" text-anchor=\"middle\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"24\">FOR PRESIDENT</text><text x=\"305\" y=\"465\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"19\">Article II take-care clause</text><text x=\"305\" y=\"500\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"19\">Spending Clause power</text><text x=\"305\" y=\"535\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"19\">South Dakota v. Dole</text><text x=\"305\" y=\"590\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Administering, not legislating</text><rect x=\"570\" y=\"350\" width=\"490\" height=\"320\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"815\" y=\"410\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"24\">FOR CONGRESS</text><text x=\"815\" y=\"465\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"19\">Article I, Section 8</text><text x=\"815\" y=\"500\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"19\">Youngstown lowest ebb</text><text x=\"815\" y=\"535\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"19\">President writing new law</text><text x=\"815\" y=\"590\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Legislating, not administering</text><rect x=\"100\" y=\"710\" width=\"900\" height=\"200\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"765\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"22\">CONSTITUTIONAL QUESTIONS</text><text x=\"550\" y=\"815\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">rarely have one obvious answer.</text><text x=\"550\" y=\"855\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Courts weigh competing claims of authority.</text><text x=\"550\" y=\"890\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Both sides have real arguments. Hear both.</text></svg>",
