            "type": "diagram",
            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">KNOWLEDGE CHECK</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Brown overturned what?</text><rect x=\"150\" y=\"220\" width=\"800\" height=\"200\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/><text x=\"550\" y=\"285\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"26\">PLESSY v. FERGUSON 1896</text><text x=\"550\" y=\"335\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">\"Separate but equal\"</text><text x=\"550\" y=\"375\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">legalized Jim Crow segregation</text><rect x=\"150\" y=\"450\" width=\"800\" height=\"200\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"550\" y=\"515\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"26\">BROWN v. BOARD 1954</text><text x=\"550\" y=\"565\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">\"Inherently unequal\"</text><text x=\"550\" y=\"605\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">unanimous, Earl Warren writing</text><rect x=\"200\" y=\"690\" width=\"700\" height=\"200\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"745\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"22\">58 YEARS LATER</text><text x=\"550\" y=\"795\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">A unanimous Court reversed itself</text><text x=\"550\" y=\"835\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">A model of overturning bad precedent</text></svg>",
