            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">AMERICAN CITIZENSHIP</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Status, rights, duties, engagement</text><rect x=\"80\" y=\"200\" width=\"940\" height=\"160\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"260\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"26\">RIGHTS</text><text x=\"550\" y=\"310\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">vote, run for office, hold passport,</text><text x=\"550\" y=\"345\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">access full Constitution</text><rect x=\"80\" y=\"390\" width=\"940\" height=\"160\" rx=\"20\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"550\" y=\"450\" text-anchor=\"middle\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"26\">DUTIES</text><text x=\"550\" y=\"500\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">obey laws, pay taxes, serve on jury,</text><text x=\"550\" y=\"535\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">register for Selective Service (males 18-25)</text><rect x=\"80\" y=\"580\" width=\"940\" height=\"160\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"550\" y=\"640\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"26\">PARTICIPATION</text><text x=\"550\" y=\"690\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">vote, volunteer, organize,</text><text x=\"550\" y=\"725\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">advocate, run for office</text><rect x=\"200\" y=\"780\" width=\"700\" height=\"200\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"835\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"22\">CITIZENSHIP IS BUILT</text><text x=\"550\" y=\"885\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Not automatic. Exercised. Renewed.</text><text x=\"550\" y=\"930\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Each generation refills it</text></svg>",
            "caption": "Three faces of being a citizen"
