            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">WISDOM</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">On the work of citizenship</text><rect x=\"100\" y=\"320\" width=\"900\" height=\"280\" rx=\"20\" fill=\"rgba(139,92,246,0.1)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"550\" y=\"420\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"32\">\"The price of freedom</text><text x=\"550\" y=\"475\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"32\">is eternal vigilance.\"</text><text x=\"950\" y=\"680\" text-anchor=\"end\" fill=\"#8b5cf6\" font-size=\"22\">- attributed to Thomas Jefferson</text><text x=\"950\" y=\"715\" text-anchor=\"end\" fill=\"#888\" font-size=\"20\">a republic must be tended</text><rect x=\"200\" y=\"800\" width=\"700\" height=\"180\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"855\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"22\">FREEDOM IS NOT INHERITED</text><text x=\"550\" y=\"900\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">It is renewed every day</text><text x=\"550\" y=\"935\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">by citizens who show up</text></svg>",
